import EventCreation from "@/components/EventApp/EventPopups/EventCreation.vue";
import EventEdit from "@/components/EventApp/EventPopups/EventEdit.vue";
import EventDeletion from "@/components/EventApp/EventPopups/EventDeletion.vue";
import SnackBar from "@/components/SnackBar.vue";
import { list_events_details } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    RegisteredUsers,
    SnackBar,
    EventEdit,
    EventDeletion,
    EventCreation
  },
  mixins: [get_location_details],
  data() {
    return {
      headers: [{
        title: "Event Name",
        key: "event_name",
        sortable: false
      }, {
        title: "Event Description",
        key: "event_description",
        sortable: false
      }, {
        title: "From Date",
        key: "from_date",
        sortable: false
      }, {
        title: "To Date",
        key: "to_date",
        sortable: false
      }, {
        title: "Status",
        key: "event_progress_status",
        sortable: false
      }, {
        title: "#Registered",
        key: "no_of_registerd_users",
        sortable: false
      }, {
        title: "Action",
        key: "action",
        sortable: false
      }],
      tableLoading: false,
      adminAppExists: false,
      tableData: [],
      componentCheck: 0,
      createEvent: false,
      SnackBarComponent: {},
      editEvent: false,
      Eventlist: false,
      eventInfo: {},
      eventDelete: false,
      locdata: [],
      next_token: null,
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      search: "",
      windowHeight: 0
    };
  },
  async created() {
    this.windowHeight = window.innerHeight - 240;
    this.fetch_admin_apps();
    await this.get_location_details();
    this.locdata = this.locationList;
    await this.fetch_event_list();
  },
  computed: {
    totalTaskCount() {
      return this.masterData ? this.masterData.length : 0;
    },
    totalCount() {
      return this.tableData.length;
    },
    startItem() {
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },
    endItem() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalCount);
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    filteredItems() {
      return this.tableData.filter(item => {
        return item.event_name.toLowerCase().includes(this.search.toLowerCase()) || item.event_description.toLowerCase().includes(this.search.toLowerCase()) || this.fetch_loc_name(item.event_visibility.visible_locations).toLowerCase().includes(this.search.toLowerCase()) || item.event_progress_status.toLowerCase().includes(this.search.toLowerCase());
      });
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      const userapp = userObj.user_apps.find(app => app.dashboard_unique_type == "EVENTS");
      // console.log(userapp, "userapp");
      if (userapp == undefined) {
        this.adminAppExists = false;
        return;
      }
      if (userapp.is_visible == false) {
        this.adminAppExists = false;
        return;
      }

      // Check if userObj and admin_apps exist
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "EVENTS_ADMINS");
      this.adminAppExists = adminExists && (adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY") && adminExists.is_dashboard_admin === true;
    },
    async updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      // Check if we need more data from API
      if (end > this.tableData.length && this.next_token) {
        await this.fetch_event_list(true);
      }
      this.paginatedItems = this.tableData.slice(start, end);
    },
    fetch_loc_name(values) {
      let names = [];
      for (let i = 0; i < values.length; i++) {
        const value = values[i];
        let name = "";
        this.locdata.forEach(element => {
          if (element.location_id === value) {
            name = element.location_name;
          }
        });
        names.push(name);
      }
      return names.join(",");
    },
    back_call() {
      this.$router.push("/home/EventsUser");
    },
    create_event() {
      this.componentCheck = 1;
      this.createEvent = true;
    },
    event_listing(item) {
      this.componentCheck = 4;
      this.Eventlist = true;
      this.eventInfo = item;
    },
    get_myteam_Pagination() {
      if (this.next_token) {
        this.fetch_event_list();
      }
    },
    async fetch_event_list() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_events_details, {
          organization_id: data.organization.organization_id,
          event_progress_status: "ALL",
          limit: 22,
          nextToken: this.next_token
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_events_details);
        this.next_token = response.nextToken;
        var dataArray = [];
        if (response.items.length > 0) {
          response.items = response.items.sort((z, y) => {
            return z.from_date - y.from_date;
          });
        }
        dataArray = response.items;
        let array = this.tableData.concat(dataArray);
        this.tableData = array;
        const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.event_id === obj.event_id));
        this.tableData = uniqueArrayOfObjects;
        this.updatePageItems();
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    edit_event(item) {
      this.eventInfo = item;
      this.componentCheck = 2;
      this.editEvent = true;
    },
    delete_event(item) {
      this.componentCheck = 3;
      this.eventDelete = true;
      this.eventInfo = item;
    },
    fetch_value(val) {
      return format_Date(val / 1000);
      // const d = new Date(parseInt(val));
      // var date = d.getDate().toLocaleString();
      // var month = (d.getMonth() + 1).toLocaleString();
      // var year = d.getFullYear();

      // return (
      //   year +
      //   "-" +
      //   (+month <= 9 ? "0" + month : month) +
      //   "-" +
      //   (+date <= 9 ? "0" + date : date)
      // );
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createEvent = false;
      this.editEvent = false;
      this.eventDelete = false;
      this.tableData = [];
      this.fetch_event_list();
    },
    handleSortChange(headers) {
      // Implement sorting logic based on the headers
      // console.log("Sorting by:", headers);
    }
  }
};
